UPDATE lab_inventory_issue_request
SET status=#{toStatus}, approved_at=#{approvedAt}, version=version+1,
    updated_by=#{actorId}, update_time=#{now}
WHERE id=#{id} AND version=#{version} AND status=#{fromStatus}

UPDATE lab_inventory_issue_request
SET status='CANCELED', version=version+1, updated_by=#{actorId}, update_time=#{now}
WHERE id=#{id} AND version=#{version} AND status=#{status}

UPDATE lab_inventory_issue_request
SET status='EXPIRED', version=version+1, updated_by=#{actorId}, update_time=#{now}
WHERE id=#{id} AND version=#{version} AND status IN ('PENDING_APPROVAL','APPROVED')

UPDATE lab_component_inventory_balance
SET reserved_quantity=reserved_quantity+#{delta}, version=version+1, update_time=#{now}
WHERE component_id=#{componentId} AND on_hand_quantity-reserved_quantity >= #{delta}

UPDATE lab_component_inventory_balance
SET reserved_quantity=reserved_quantity-#{delta}, version=version+1, update_time=#{now}
WHERE component_id=#{componentId} AND reserved_quantity >= #{delta}

UPDATE lab_inventory_batch
SET reserved_quantity=reserved_quantity+#{delta}
WHERE id=#{batchId} AND current_quantity-reserved_quantity >= #{delta}

UPDATE lab_inventory_batch
SET reserved_quantity=reserved_quantity-#{delta}
WHERE id=#{batchId} AND reserved_quantity >= #{delta}

UPDATE lab_inventory_issue_line
SET reserved_quantity=reserved_quantity-#{delta}
WHERE id=#{lineId} AND reserved_quantity >= #{delta}

