        SELECT 1 FROM lab_project_member pm
        WHERE pm.project_id=r.project_id AND pm.user_id=#{userId}
          AND pm.project_role IN ('OWNER','MAINTAINER')
    )
)

AND EXISTS(
    SELECT 1 FROM lab_inventory_issue_line l
    WHERE l.request_id=r.id AND l.component_id=#{componentId}
