UPDATE lab_component_inventory_balance
SET on_hand_quantity=on_hand_quantity-#{delta},
    reserved_quantity=reserved_quantity-#{delta},
    version=version+1, update_time=#{now}
WHERE component_id=#{componentId}
  AND on_hand_quantity >= #{delta} AND reserved_quantity >= #{delta}

UPDATE lab_inventory_batch
SET current_quantity=current_quantity-#{delta},
    reserved_quantity=reserved_quantity-#{delta}
WHERE id=#{batchId}
  AND current_quantity >= #{delta} AND reserved_quantity >= #{delta}
